class Solution {
    public int deepestLeavesSum(TreeNode root){
        Queue<TreeNode> queue=new ArrayDeque<>();
        queue.offer(root);
        int sum=0;
        while(!queue.isEmpty()){
            int size=queue.size();
            sum=0;
            while(size-->0){
                TreeNode node=queue.poll();
                sum+=node.val;
                if(node.left!=null)queue.offer(node.left);
                if(node.right!=null)queue.offer(node.right);
            }
        }
        return sum;
    }
}

